class Trie {
    constructor() {
        this.child = new Array(26).fill(null);
        this.id = -1;
    }
}

/**
 * @param {string} source
 * @param {string} target
 * @param {string[]} original
 * @param {string[]} changed
 * @param {number[]} cost
 * @return {number}
 */
var minimumCost = (source, target, original, changed, cost) => {
    const n = source.length;
    const m = original.length;
    const root = new Trie();

    const pos = { value: -1 };
    const nodeCount = m * 2;
    const dp = Array.from({ length: nodeCount }, () => Array(nodeCount).fill(Infinity));

    for (let i = 0; i < nodeCount; i++) {
        dp[i][i] = 0;
    }

    for (let i = 0; i < m; i++) {
        const x = add(root, original[i], pos);
        const y = add(root, changed[i], pos);
        dp[x][y] = Math.min(dp[x][y], cost[i]);
    }

    const size = pos.value + 1;
    for (let k = 0; k < size; k++) {
        for (let i = 0; i < size; i++) {
            for (let j = 0; j < size; j++) {
                dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k][j]);
            }
        }
    }

    const resDp = new Array(n).fill(-1);
    for (let j = 0; j < n; j++) {
        if (j > 0 && resDp[j - 1] === -1) {
            continue;
        }

        const base = j === 0 ? 0 : resDp[j - 1];
        if (source[j] === target[j]) {
            if (resDp[j] === -1 || base < resDp[j]) {
                resDp[j] = base;
            }
        }

        let u = root;
        let v = root;
        for (let i = j; i < n; i++) {
            u = u.child[source.charCodeAt(i) - "a".charCodeAt(0)];
            v = v.child[target.charCodeAt(i) - "a".charCodeAt(0)];

            if (!u || !v) {
                break;
            }

            if (u.id !== -1 && v.id !== -1 && dp[u.id][v.id] !== Infinity) {
                const newVal = base + dp[u.id][v.id];
                if (resDp[i] === -1 || newVal < resDp[i]) {
                    resDp[i] = newVal;
                }
            }
        }
    }

    return resDp[n - 1];
};

const add = (node, word, index) => {
    for (const ch of word) {
        const i = ch.charCodeAt(0) - "a".charCodeAt(0);
        if (!node.child[i]) {
            node.child[i] = new Trie();
        }
        node = node.child[i];
    }

    if (node.id === -1) {
        node.id = ++index.value;
    }

    return node.id;
};
